        rule: { ru: 'send = «отправлять, кидать». my email = «моя почта». I send you my email = «я кидаю тебе почту».', uk: 'send = «відправляти, кидати». my email = «моя пошта». I send you my email = «я кидаю тобі пошту».', es: 'send = «mandar». my email = «mi correo». I send you my email = «te mando mi correo».' , 'pt-BR': 'send = “enviar”. my email = "meu e-mail". I send you my email = "Estou enviando meu e-mail para você."', vi: 'send = “gửi”. my email = "email của tôi". I send you my email = "Tôi đang gửi email cho bạn."', id: 'send = “kirim”. my email = "email saya". I send you my email = "Saya mengirimkan email saya."', tr: 'send = “gönder”. my email = "e-posta adresim". I send you my email = "Size e-postamı gönderiyorum."', pl: 'send = „wyślij”. my email = „mój e-mail”. I send you my email = "Wysyłam Ci mój e-mail."'},
        why: { ru: 'Сначала кому (you), потом что (my email). Такой порядок звучит естественно в чате.', uk: 'Спершу кому (you), потім що (my email). Такий порядок звучить природно в чаті.', es: 'Primero a quién (you), luego qué (my email). Ese orden suena natural en el chat.' , 'pt-BR': 'Primeiro para quem (you), depois o quê (my email). Essa ordem parece natural no chat.', vi: 'Đầu tiên là với ai (you), sau đó là cái gì (my email). Thứ tự đó nghe có vẻ tự nhiên trong chat.', id: 'Pertama kepada siapa (you), lalu apa (my email). Urutan itu terdengar wajar di chat.', tr: 'Önce kime (you), sonra neye (my email). Bu sıra chat\'de doğal görünüyor.', pl: 'Najpierw komu (you), potem co (my email). Ta kolejność brzmi naturalnie w chat.'},
        commonMistake: { ru: 'Не меняй местами: говори send you my email, а не send my email you.', uk: 'Не міняй місцями: кажи send you my email, а не send my email you.', es: 'No cambies el orden: di send you my email, no send my email you.' , 'pt-BR': 'Não altere a ordem: diga send you my email, não send my email you.', vi: 'Không thay đổi thứ tự: nói send you my email chứ không phải send my email you.', id: 'Jangan ubah urutannya: ucapkan send you my email, bukan send my email you.', tr: 'Sırayı değiştirmeyin: send my email you değil, send you my email deyin.', pl: 'Nie zmieniaj kolejności: powiedz send you my email, a nie send my email you.'},
