        rule: { ru: 'add = «добавить». you = «тебя». meeting = «встреча». I will add you = «я добавлю тебя».', uk: 'add = «додати». you = «тебе». meeting = «зустріч». I will add you = «я додам тебе».', es: 'add = «añadir». you = «te». meeting = «reunión». I will add you = «te añadiré».' , 'pt-BR': 'add = “aadicionar”. you = “te”. meeting = “reunião”. I will add you = "Vou aadicionar você."', vi: 'add = “athêm”. you = “tê”. meeting = “cuộc họp”. I will add you = "Tôi sẽ athêm bạn."', id: 'add = “atambahkan”. you = “te”. meeting = “pertemuan”. I will add you = "Saya akan amenambahkan Anda."', tr: 'add = “aekle”. you = "te". meeting = “toplantı”. I will add you = "Seni aekleyeceğim."', pl: 'add = „adodaj”. you = „te”. meeting = „spotkanie”. I will add you = "Dodam Cię a."'},
        why: { ru: 'Сначала кого (you), потом куда (to the meeting). Такой порядок звучит естественно.', uk: 'Спершу кого (you), потім куди (to the meeting). Такий порядок звучить природно.', es: 'Primero a quién (you), luego a dónde (to the meeting). Ese orden suena natural.' , 'pt-BR': 'Primeiro a quem (you), depois a onde (to the meeting). Essa ordem parece natural.', vi: 'Đầu tiên là a ai (you), sau đó là a ở đâu (to the meeting). Thứ tự đó nghe có vẻ tự nhiên.', id: 'Pertama a siapa (you), lalu a di mana (to the meeting). Urutan itu terdengar wajar.', tr: 'Önce a kim (you), sonra a burada (to the meeting). Bu sıralama kulağa doğal geliyor.', pl: 'Najpierw a kto (you), następnie a gdzie (to the meeting). Ta kolejność brzmi naturalnie.'},
        commonMistake: { ru: 'После add сразу you: говори add you to, а не add to you.', uk: 'Після add одразу you: кажи add you to, а не add to you.', es: 'Tras add va you directo: di add you to, no add to you.' , 'pt-BR': 'Depois que add vai direto para you: diga add you to, não add to you.', vi: 'Sau add chuyển thẳng you: nói add you to chứ không phải add to you.', id: 'Setelah add langsung menjadi you: ucapkan add you to, bukan add to you.', tr: 'add doğrudan you gittikten sonra: add to you değil, add you to deyin.', pl: 'Po add idzie bezpośrednio you: powiedz add you to, a nie add to you.'},
